// canvas.me mark: a minimal block "C" drawn like the SETITUP mark: bars inset one
// block, terminals stepping past them, same gradient. Generated by scripts/pixel_logo.py.
// `id` keeps gradient ids unique when several marks share a page.
export function LogoMark({ size = 24, id = "cm" }: { size?: number; id?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 400 400" fill="none" aria-hidden>
      <defs>
        <linearGradient id={`${id}-g`} x1="200" y1="0" x2="200" y2="400" gradientUnits="userSpaceOnUse">
          <stop stopColor="#9D7FF4" />
          <stop offset="1" stopColor="#0755FF" />
        </linearGradient>
      </defs>
      <path fill={`url(#${id}-g)`} d="M300.0 12.0L300.0 50.0L388.0 50.0A12 12 0 0 1 400.0 62.0L400.0 88.0A12 12 0 0 1 388.0 100.0L112.0 100.0A12 12 0 0 0 100.0 112.0L100.0 288.0A12 12 0 0 0 112.0 300.0L388.0 300.0A12 12 0 0 1 400.0 312.0L400.0 338.0A12 12 0 0 1 388.0 350.0L300.0 350.0L300.0 388.0A12 12 0 0 1 288.0 400.0L62.0 400.0A12 12 0 0 1 50.0 388.0L50.0 350.0L12.0 350.0A12 12 0 0 1 0.0 338.0L0.0 62.0A12 12 0 0 1 12.0 50.0L50.0 50.0L50.0 12.0A12 12 0 0 1 62.0 0.0L288.0 0.0A12 12 0 0 1 300.0 12.0Z" />
    </svg>
  );
}

export function Logo({
  size = 22,
  id,
  className = "",
  textClassName = "",
}: {
  size?: number;
  id?: string;
  className?: string;
  textClassName?: string;
}) {
  return (
    <span className={`inline-flex items-center gap-2 font-bold tracking-[-0.01em] text-ink-900 ${className}`}>
      <LogoMark size={size} id={id} />
      <span className={textClassName}>
        canvas<span className="text-accent-500">.me</span>
      </span>
    </span>
  );
}
